// ---------------------------------------------------------------------------
// The contract: where Go keeps a key, it must agree with Python
// ---------------------------------------------------------------------------

// testdata holds eight inputs and, beside each, the effective config the
// PYTHON loader produces for it (generated by make-golden.py). This test
// loads the same inputs here and compares every key the Go tree still models.
//
// It cannot be a whole-file diff: Go drops `findings`, `dashboard.kanban` and
// the multi-provider tunnel block, and adds `publish`. What must hold is
// narrower and more useful — for every key BOTH implementations have, the two
// loaders agree. A silent divergence in `concurrency.global_max` or
// `retry.backoff_seconds` would change dispatch behaviour on a project whose
// owner only swapped the binary.
func TestEffectiveConfigMatchesThePythonGoldens(t *testing.T) {
	inputs, err := filepath.Glob("testdata/*.input.yaml")
	if err != nil {
		t.Fatalf("glob testdata: %v", err)
	}
	if len(inputs) < 8 {
		t.Fatalf("found %d inputs, expected the 8 generated cases", len(inputs))
	}

	for _, in := range inputs {
		name := strings.TrimSuffix(filepath.Base(in), ".input.yaml")
		t.Run(name, func(t *testing.T) {
			goldenPath := filepath.Join("testdata", name+".effective.yaml")
			raw, err := os.ReadFile(goldenPath) // #nosec G304 -- fixed testdata path
			if err != nil {
				t.Fatalf("read golden: %v", err)
			}
			var py map[string]any
			if err := yaml.Unmarshal(raw, &py); err != nil {
				t.Fatalf("parse golden: %v", err)
			}

			res, err := Load(in, "testdata")
			if name == "backend-file" {
				// Python happily loads `backend: file`; Go refuses. That is
				// the one documented divergence, and it is the point of the
				// case, so assert the refusal instead of the values.
				if !errors.Is(err, ErrFileBackend) {
					t.Fatalf("loading a file-backend config returned %v, want ErrFileBackend", err)
				}
				return
			}
			if err != nil {
				t.Fatalf("Load: %v", err)
			}
			got := res.Config

			checks := []struct {
				path string
				got  any
			}{
				{"concurrency.global_max", got.Concurrency.GlobalMax},
				{"default_timeout_multiplier", got.DefaultTimeoutMult},
				{"budget.per_dispatch_usd", got.Budget.PerDispatchUSD},
				{"retry.max_attempts", got.Retry.MaxAttempts},
				{"retry.backoff_seconds", got.Retry.BackoffSeconds},
				{"retry.rate_limit_backoff_seconds", got.Retry.RateLimitBackoffSeconds},
				{"spec_root", got.SpecRoot},
				{"budgets_config", got.BudgetsConfig},
				{"budgets_preset", got.BudgetsPreset},
				{"typical_dispatch_tokens", got.TypicalDispatchToken},
				{"dispatch.worktree_mode", got.Dispatch.WorktreeMode},
				{"dispatch.base_branch", got.Dispatch.BaseBranch},
				{"vcs.provider", got.VCS.Provider},
				{"vcs.host", got.VCS.Host},
				{"vcs.auto_pr", got.VCS.AutoPR},
				{"vcs.ci_max_retries", got.VCS.CIMaxRetries},
				{"vcs.ci_poll_interval_s", got.VCS.CIPollIntervalS},
				{"github.test_command", got.GitHub.TestCommand},
				{"github.auto_merge", got.GitHub.AutoMerge},
				{"notifications.slack_webhook", got.Notifications.SlackWebhook},
				{"notifications.discord_webhook", got.Notifications.DiscordWebhook},
				{"notifications.timeout_s", got.Notifications.TimeoutS},
			}
			for _, c := range checks {
				want, ok := lookup(py, c.path)
				if !ok {
					t.Errorf("%s is absent from the Python golden — the key was "+
						"renamed or dropped upstream", c.path)
					continue
				}
				if !sameScalar(c.got, want) {
					t.Errorf("%s: Go says %v (%T), Python says %v (%T)",
						c.path, c.got, c.got, want, want)
				}
			}

			// The status labels are what the client reads; a divergence here
			// is visible in the stakeholder view.
			wantLabels, ok := lookup(py, "presentation.status_labels")
			if !ok {
				t.Fatal("presentation.status_labels missing from the golden")
			}
			wl, _ := wantLabels.(map[string]any)
			for k, want := range wl {
				if got.Presentation.StatusLabels[k] != want {
					t.Errorf("presentation.status_labels[%q]: Go %q, Python %v",
						k, got.Presentation.StatusLabels[k], want)
				}
			}
		})
	}
}

// lookup walks a dotted path through the decoded YAML.
func lookup(m map[string]any, path string) (any, bool) {
	cur := any(m)
	for _, seg := range strings.Split(path, ".") {
		mm, ok := cur.(map[string]any)
		if !ok {
			return nil, false
		}
		cur, ok = mm[seg]
		if !ok {
			return nil, false
		}
	}
	return cur, true
}

// sameScalar compares across YAML's int/float ambiguity: Python writes 5.0
// where Go holds a float64, and 6 where Go holds an int.
func sameScalar(got, want any) bool {
	switch g := got.(type) {
	case int:
		switch w := want.(type) {
		case int:
			return g == w
		case float64:
			return float64(g) == w
		}
	case float64:
		switch w := want.(type) {
		case int:
			return g == float64(w)
		case float64:
			return g == w
		}
	case string:
		w, ok := want.(string)
		return ok && g == w
	case bool:
		w, ok := want.(bool)
		return ok && g == w
	}
	return false
}

// ---------------------------------------------------------------------------
// The one refusal
// ---------------------------------------------------------------------------

func TestFileBackendIsAnErrorWithTheWayOut(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")
	write(t, path, "state:\n  backend: file\n")

	_, err := Load(path, dir)
	if !errors.Is(err, ErrFileBackend) {
		t.Fatalf("got %v, want ErrFileBackend", err)
	}
	// An error that only says "unsupported" leaves the operator stuck with a
	// project they cannot open. It has to name the command that fixes it.
	if !strings.Contains(err.Error(), "orch migrate") {
		t.Errorf("the error does not tell the operator what to run: %v", err)
	}
}

func TestBackendCases(t *testing.T) {
	cases := []struct {
		name    string
		yaml    string
		want    string
		wantErr bool
	}{
		{"absent defaults to sqlite", "", "sqlite", false},
		{"explicit sqlite", "state:\n  backend: sqlite\n", "sqlite", false},
		{"empty string defaults", "state:\n  backend: \"\"\n", "sqlite", false},
		{"case and space tolerated", "state:\n  backend: \" SQLite \"\n", "sqlite", false},
		{"file is refused", "state:\n  backend: file\n", "", true},
		{"nonsense is refused", "state:\n  backend: postgres\n", "", true},
	}
	for _, c := range cases {
		t.Run(c.name, func(t *testing.T) {
			dir := t.TempDir()
			path := filepath.Join(dir, "config.yaml")
			write(t, path, c.yaml)
			res, err := Load(path, dir)
			if c.wantErr {
				if err == nil {
					t.Fatalf("expected an error, got backend %q", res.Config.State.Backend)
				}
				return
			}
			if err != nil {
				t.Fatalf("Load: %v", err)
			}
			if res.Config.State.Backend != c.want {
				t.Errorf("backend = %q, want %q", res.Config.State.Backend, c.want)
			}
		})
	}
}

// ---------------------------------------------------------------------------
// Dropped keys warn once and never fail
// ---------------------------------------------------------------------------

func TestDroppedKeysWarnButLoad(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")
	write(t, path, `
findings:
  publish_repo: "someone/somewhere"
  label: auto-reported
dashboard:
  board_url: "https://draw.example.invalid/editor/abc"
  profile: operator
spec_root: docs/specs
`)
	res, err := Load(path, dir)
	if err != nil {
		t.Fatalf("a config with dropped keys must still load: %v", err)
	}
	if res.Config.SpecRoot != "docs/specs" {
		t.Errorf("the keys we DO read were lost: spec_root = %q", res.Config.SpecRoot)
	}

	joined := strings.Join(res.Warnings, "\n")
	for _, want := range []string{"findings", "dashboard.board_url"} {
		if !strings.Contains(joined, want) {
			t.Errorf("no warning mentions %q:\n%s", want, joined)
		}
	}
	// One line for the whole `findings` section, not one per leaf.
	n := 0
	for _, w := range res.Warnings {
		if strings.HasPrefix(w, "ignoring `findings`") {
			n++
		}
	}
	if n != 1 {
		t.Errorf("expected a single warning for the findings section, got %d:\n%s", n, joined)
	}
}

func TestWarningsAreSortedAndDeduplicated(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")
	write(t, path, "zzz_unknown: 1\naaa_unknown: 2\nfindings:\n  publish_repo: x\n")
	res, err := Load(path, dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if len(res.Warnings) != 3 {
		t.Fatalf("want 3 warnings, got %d: %v", len(res.Warnings), res.Warnings)
	}
	for i := 1; i < len(res.Warnings); i++ {
		if res.Warnings[i-1] > res.Warnings[i] {
			t.Errorf("warnings are not sorted: %v", res.Warnings)
			break
		}
	}
}

func TestKnownKeysDoNotWarn(t *testing.T) {
	res, err := Load("testdata/packaged.input.yaml", "testdata")
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	// The packaged config is the fullest one we ship. Anything it contains
	// that Go does not read should be a DELIBERATE drop with an explanation,
	// not an "orch does not read this key" line.
	for _, w := range res.Warnings {
		if strings.Contains(w, "orch does not read this key") {
			t.Errorf("the packaged config produced an unexplained warning: %s", w)
		}
	}
}

// ---------------------------------------------------------------------------
// H-2 compatibility: a project-root dashboard.yaml still wins
// ---------------------------------------------------------------------------

func TestRootDashboardYAMLDeepMerges(t *testing.T) {
	dir := t.TempDir()
	cfg := filepath.Join(dir, ".orchestrator", "config.yaml")
	if err := os.MkdirAll(filepath.Dir(cfg), 0o750); err != nil {
		t.Fatal(err)
	}
	write(t, cfg, "dashboard:\n  profile: operator\n  summary_language: es\nspec_root: specs\n")
	write(t, filepath.Join(dir, "dashboard.yaml"),
		"dashboard:\n  summary_language: en\n  show_spend_to_stakeholder: true\n")

	res, err := Load(cfg, dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	if res.Config.Dashboard.SummaryLanguage != "en" {
		t.Errorf("the override lost: summary_language = %q", res.Config.Dashboard.SummaryLanguage)
	}
	if !res.Config.Dashboard.ShowSpendToStakeholder {
		t.Error("a key present only in the override was dropped")
	}
	// Deep merge, not replace: a sibling the override did not mention stays.
	if res.Config.Dashboard.Profile != "operator" {
		t.Errorf("the merge clobbered a sibling key: profile = %q", res.Config.Dashboard.Profile)
	}
	if res.Config.SpecRoot != "specs" {
		t.Errorf("the merge clobbered a sibling section: spec_root = %q", res.Config.SpecRoot)
	}
	if len(res.Sources) != 2 {
		t.Errorf("Sources = %v, want both files", res.Sources)
	}
}

func TestMissingConfigIsNotAnError(t *testing.T) {
	dir := t.TempDir()
	res, err := Load(filepath.Join(dir, "nope.yaml"), dir)
	if err != nil {
		t.Fatalf("a missing config must fall back to defaults: %v", err)
	}
	if res.Config.SpecRoot != "specs" {
		t.Errorf("defaults not applied: spec_root = %q", res.Config.SpecRoot)
	}
	if len(res.Sources) != 0 {
		t.Errorf("Sources = %v, want empty", res.Sources)
	}
}

// ---------------------------------------------------------------------------
// Retry (F4.6)
// ---------------------------------------------------------------------------

func TestRetryPerClassOverridesTheScalars(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")
	write(t, path, `
retry:
  max_attempts: 2
  backoff_seconds: 5
  rate_limit_backoff_seconds: 60
  rate_limit:
    max_attempts: 5
  version_drift:
    max_attempts: 0
    escalate_model: true
`)
	res, err := Load(path, dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	r := res.Config.Retry

	if got := r.RateLimit.Attempts(r.MaxAttempts); got != 5 {
		t.Errorf("rate_limit.max_attempts = %d, want the per-class 5", got)
	}
	if got := r.RateLimit.Backoff(r.RateLimitBackoffSeconds); got != 60 {
		t.Errorf("rate_limit backoff = %v, want the scalar 60 to seed it", got)
	}
	// The reason RetryRule uses pointers: 0 means "never retry", which a
	// zero value could not distinguish from "unset".
	if got := r.VersionDrift.Attempts(r.MaxAttempts); got != 0 {
		t.Errorf("version_drift.max_attempts = %d, want an explicit 0", got)
	}
	if !r.VersionDrift.Escalate() {
		t.Error("version_drift.escalate_model was lost")
	}
	// A class with no block at all inherits.
	if got := r.Transient.Attempts(r.MaxAttempts); got != 2 {
		t.Errorf("transient inherited %d, want the scalar 2", got)
	}
	if r.Transient.Escalate() {
		t.Error("escalate_model defaulted to true")
	}
}

func TestRetryLegacyScalarsAloneStillWork(t *testing.T) {
	dir := t.TempDir()
	path := filepath.Join(dir, "config.yaml")
	write(t, path, "retry:\n  backoff_seconds: 9\n  rate_limit_backoff_seconds: 120\n")
	res, err := Load(path, dir)
	if err != nil {
		t.Fatalf("Load: %v", err)
	}
	r := res.Config.Retry
	if got := r.Transient.Backoff(r.BackoffSeconds); got != 9 {
		t.Errorf("transient backoff = %v, want the scalar 9", got)
	}
	if got := r.RateLimit.Backoff(r.RateLimitBackoffSeconds); got != 120 {
		t.Errorf("rate_limit backoff = %v, want the scalar 120", got)
	}
}

