func TestDefaultProjectIDSkipsGenericBasenames(t *testing.T) {
	cases := []struct{ root, want string }{
		{"/srv/example-project/orch", "orch"},
		{"/srv/example-project/orch/v2", "orch"},
		{"/srv/example-project/orch/src", "orch"},
		{"/srv/example-project/orch/apps", "orch"},
		{"/srv/billing-api", "billing-api"},
		{"/", "unknown"},
	}
	for _, c := range cases {
		if got := DefaultProjectID(c.root); got != c.want {
			t.Errorf("DefaultProjectID(%q) = %q, want %q", c.root, got, c.want)
		}
	}
}

func TestStateDirLayout(t *testing.T) {
	legacy := Paths{Root: "/p", ID: "proj", Layout: LayoutLegacy}
	if got, want := legacy.StateDir(), filepath.Join("/p", ".orchestrator", "state"); got != want {
		t.Errorf("legacy StateDir = %q, want %q", got, want)
	}
	ns := Paths{Root: "/p", ID: "proj", Layout: LayoutNamespaced}
	if got, want := ns.StateDir(), filepath.Join("/p", ".orchestrator", "state", "proj"); got != want {
		t.Errorf("namespaced StateDir = %q, want %q", got, want)
	}
}

func TestExplicitRootSelectsTheNamespacedLayout(t *testing.T) {
	dir := t.TempDir()
	p, err := ResolvePaths(dir, "", "")
	if err != nil {
		t.Fatalf("ResolvePaths: %v", err)
	}
	if p.Layout != LayoutNamespaced {
		t.Errorf("an explicit root gave layout %q, want namespaced", p.Layout)
	}
}

// Issue #84: a project previously run with an explicit root already has a
// namespaced directory. Missing that means `orch dashboard` started from
// inside the project reads an empty legacy database while the CLI writes the
// namespaced one — two truths, no error anywhere.
func TestExistingNamespacedStateIsDetected(t *testing.T) {
	dir := t.TempDir()
	id := DefaultProjectID(dir)
	nsDir := filepath.Join(dir, ".orchestrator", "state", id)
	if err := os.MkdirAll(nsDir, 0o750); err != nil {
		t.Fatal(err)
	}
	write(t, filepath.Join(nsDir, "orch.db"), "not really a database")

	t.Setenv("ORCH_PROJECT_ROOT", "")
	t.Chdir(dir)
	p, err := ResolvePaths("", "", "")
	if err != nil {
		t.Fatalf("ResolvePaths: %v", err)
	}
	if p.Layout != LayoutNamespaced {
		t.Errorf("layout = %q; existing namespaced state should have been detected", p.Layout)
	}
}

// Issue #229: `scripts/task-finish.sh` passes `--project-root .`, which is
// explicit, so it resolved the namespaced layout while `orch run` started from
// inside the project wrote the legacy one. The agent's verdict landed in a
// fresh database nobody read.
func TestExplicitRootKeepsExistingLegacyState(t *testing.T) {
	dir := t.TempDir()
	if err := os.MkdirAll(filepath.Join(dir, ".orchestrator", "state"), 0o750); err != nil {
		t.Fatal(err)
	}
	write(t, filepath.Join(dir, ".orchestrator", "state", "orch.db"), "not really a database")

	p, err := ResolvePaths(dir, "", "")
	if err != nil {
		t.Fatalf("ResolvePaths: %v", err)
	}
	if p.Layout != LayoutLegacy {
		t.Errorf("layout = %q; an explicit root must keep the legacy state it already has", p.Layout)
	}
}

// Issue #229: an agent dispatched into `.worktrees/<ID>` runs `orch mcp` and
// the task scripts from there. `.orchestrator/` is gitignored, so resolving
// the worktree as the project bootstrapped a second database inside it.
func TestWorktreeResolvesToItsProject(t *testing.T) {
	root := t.TempDir()
	if err := os.MkdirAll(filepath.Join(root, ".orchestrator"), 0o750); err != nil {
		t.Fatal(err)
	}
	wt := filepath.Join(root, ".worktrees", "F1.T1")
	if err := os.MkdirAll(wt, 0o750); err != nil {
		t.Fatal(err)
	}

	t.Setenv("ORCH_PROJECT_ROOT", "")
	for name, arg := range map[string]string{"cwd": "", "explicit": wt} {
		t.Run(name, func(t *testing.T) {
			t.Chdir(wt)
			p, err := ResolvePaths(arg, "", "")
			if err != nil {
				t.Fatalf("ResolvePaths: %v", err)
			}
			if p.Root != root {
				t.Errorf("Root = %q, want the worktree's project %q", p.Root, root)
			}
			if p.ID != DefaultProjectID(root) {
				t.Errorf("ID = %q, want %q", p.ID, DefaultProjectID(root))
			}
		})
	}
}

// #249 moved worktrees out of the checkout, to `<project>.worktrees/<ID>`
// beside it. A person who cds into one, and `scripts/task-*.sh`, which pass
// `--project-root .`, still reach the project's database.
func TestSiblingWorktreeResolvesToItsProject(t *testing.T) {
	root := filepath.Join(t.TempDir(), "usebot")
	if err := os.MkdirAll(filepath.Join(root, ".orchestrator"), 0o750); err != nil {
		t.Fatal(err)
	}
	wt := filepath.Join(root+".worktrees", "F1.T1")
	if err := os.MkdirAll(wt, 0o750); err != nil {
		t.Fatal(err)
	}

	t.Setenv("ORCH_PROJECT_ROOT", "")
	t.Setenv("ORCH_PROJECT_ID", "")
	for name, arg := range map[string]string{"cwd": "", "explicit": wt, "dot": "."} {
		t.Run(name, func(t *testing.T) {
			t.Chdir(wt)
			p, err := ResolvePaths(arg, "", "")
			if err != nil {
				t.Fatalf("ResolvePaths: %v", err)
			}
			if p.Root != root {
				t.Errorf("Root = %q, want the worktree's project %q", p.Root, root)
			}
			if p.ID != "usebot" {
				t.Errorf("ID = %q, want usebot", p.ID)
			}
		})
	}
}

// A dispatched child gets ORCH_PROJECT_ROOT from the engine, so it resolves
// the project from wherever it runs, even a directory no path rule knows.
func TestProjectRootEnvWinsOverTheWorkingDirectory(t *testing.T) {
	root := t.TempDir()
	t.Setenv("ORCH_PROJECT_ROOT", root)
	t.Chdir(t.TempDir())
	p, err := ResolvePaths("", "", "")
	if err != nil {
		t.Fatalf("ResolvePaths: %v", err)
	}
	if p.Root != root {
		t.Errorf("Root = %q, want ORCH_PROJECT_ROOT's %q", p.Root, root)
	}
}

// A `.worktrees/` directory that is not orch's (no .orchestrator/ above it)
// is left alone, in either layout.
func TestUnrelatedWorktreesDirIsNotRewritten(t *testing.T) {
	base := t.TempDir()
	// A sibling layout whose "project" exists but is not orch's.
	if err := os.MkdirAll(filepath.Join(base, "app"), 0o750); err != nil {
		t.Fatal(err)
	}
	for _, wt := range []string{
		filepath.Join(base, ".worktrees", "x"),
		filepath.Join(base, "app.worktrees", "x"),
	} {
		if err := os.MkdirAll(wt, 0o750); err != nil {
			t.Fatal(err)
		}
		p, err := ResolvePaths(wt, "", "")
		if err != nil {
			t.Fatalf("ResolvePaths: %v", err)
		}
		if p.Root != wt {
			t.Errorf("Root = %q, want %q unchanged", p.Root, wt)
		}
	}
}

